<?php $role = $this->session->userdata('permissao');
$equipmentDate = function ($date, $time = false) {
    return $date && strtotime($date) ? date($time ? 'd/m/Y H:i' : 'd/m/Y', strtotime($date)) : 'Não informada';
}; ?>
<section class="ui-page" aria-labelledby="equipment-detail-title">
<header class="ui-page-header"><div><p class="ui-eyebrow">EQUIPAMENTO #<?= (int) $equipment->idEquipamentos ?></p><h1 id="equipment-detail-title"><?= html_escape($equipment->equipamento) ?></h1><p>Identificação, fotos de cadastro e histórico de atendimentos.</p></div><div class="ui-row-actions"><?php if ($this->permission->checkPermission($role, 'eCliente')) { ?><a class="ui-button ui-button-primary" href="<?= site_url('equipamentos/salvar/' . (int) $equipment->idEquipamentos) ?>">Editar equipamento</a><?php } ?><a class="ui-button" href="<?= site_url('equipamentos/etiqueta/' . (int) $equipment->idEquipamentos) ?>" target="_blank" rel="noopener">Imprimir etiqueta QR</a><a class="ui-button" href="<?= site_url('equipamentos') ?>">Voltar aos equipamentos</a></div></header>
<div class="ui-card"><h2>Identificação e cliente</h2><dl class="ui-detail-grid"><div><dt>Cliente</dt><dd><a href="<?= site_url('clientes/visualizar/' . (int) $equipment->clientes_id) ?>"><?= html_escape(html_entity_decode($equipment->nomeCliente, ENT_QUOTES | ENT_HTML5, 'UTF-8')) ?></a></dd></div>
<?php foreach (['marca' => 'Marca', 'modelo' => 'Modelo', 'num_serie' => 'Número de série', 'cor' => 'Cor', 'descricao' => 'Observações do cadastro'] as $field => $label) { ?><div><dt><?= html_escape($label) ?></dt><dd><?= html_escape($equipment->$field ?: 'Não informado') ?></dd></div><?php } ?></dl></div>
<div class="ui-card ui-card-following"><h2>Fotos do cadastro</h2><p class="ui-hint">Estas fotos identificam o equipamento. As condições de recebimento e entrega devem ser registradas nas vistorias de cada OS.</p>
<?php if ($photos) { ?><div class="ui-photo-grid"><?php foreach ($photos as $index => $photo) { ?><figure><a href="<?= site_url('equipamentos/foto/' . (int) $photo['id']) ?>" target="_blank" rel="noopener"><img src="<?= site_url('equipamentos/foto/' . (int) $photo['id']) ?>" alt="Foto <?= (int) $index + 1 ?> do equipamento #<?= (int) $equipment->idEquipamentos ?>; abrir imagem" loading="lazy"></a><figcaption><?= html_escape($equipmentDate($photo['created_at'], true)) ?></figcaption></figure><?php } ?></div><?php } else { ?><p class="ui-empty">Nenhuma foto cadastrada para este equipamento.</p><?php } ?>
<?php if ($this->permission->checkPermission($role, 'eCliente')) { ?><?php if (count($photos) < 12) { ?><?= form_open_multipart('equipamentos/adicionarFoto/' . (int) $equipment->idEquipamentos, ['class' => 'ui-search ui-card-following']) ?><div><label for="equipment-photo">Adicionar foto ao cadastro</label><input type="file" id="equipment-photo" name="foto" accept="image/jpeg,image/png" required aria-describedby="equipment-photo-help"><p class="ui-hint" id="equipment-photo-help">JPEG ou PNG, até 2 MB e 12 MP. <?= count($photos) ?> de 12 fotos cadastradas.</p></div><button type="submit" class="ui-button ui-button-primary">Registrar foto</button></form><?php } else { ?><p class="ui-notice">O limite de 12 fotos do cadastro foi atingido.</p><?php } ?><?php } ?></div>
<?php if (isset($history)) { ?><div class="ui-card ui-card-following"><h2>Histórico de ordens de serviço</h2><p class="ui-hint">Até 100 atendimentos vinculados a este equipamento. O vínculo por si só não confirma o recebimento físico.</p><p class="ui-table-hint">Deslize a tabela para consultar todos os dados.</p><div class="ui-table-scroll" role="region" aria-label="Histórico do equipamento" tabindex="0"><table class="ui-table ui-history-table"><caption class="ui-sr-only">Histórico de ordens de serviço do equipamento</caption><thead><tr><th scope="col">OS</th><th scope="col">Situação</th><th scope="col">Abertura</th><th scope="col">Entrega registrada</th><th scope="col">Ações</th></tr></thead><tbody><?php foreach ($history as $order) { ?><tr><td>#<?= (int) $order->idOs ?></td><td><span class="ui-badge"><?= html_escape($order->status) ?></span></td><td><?= html_escape($equipmentDate($order->dataInicial)) ?></td><td><?= html_escape($equipmentDate($order->entregue_em, true)) ?></td><td><a class="ui-button ui-button-small" href="<?= site_url('os/visualizar/' . (int) $order->idOs) ?>">Ver OS #<?= (int) $order->idOs ?></a></td></tr><?php } ?><?php if (! $history) { ?><tr><td class="ui-empty" colspan="5">Nenhuma OS vinculada. Selecione este equipamento ao abrir a OS do cliente.</td></tr><?php } ?></tbody></table></div></div><?php } ?></section>
